mapper.select:
SELECT i.point_id, i.cart_id, i.point_code, p.point_name, l.location_name, a.aisle_name, c.cart_code, i.arrive_time, i.arrive_quantity, -- 实时装载量：一次聚合在车(status=1)数量，替代逐行子查询 COALESCE(ci.cnt, 0) AS current_quantity, i.lock_status, i.remark, su.nickname AS updated_by_name, i.updated_time FROM wms_cart_inventory i LEFT JOIN wms_location l ON l.id = i.location_id LEFT JOIN wms_aisle a ON a.id = i.aisle_id LEFT JOIN wms_point p ON p.id = i.point_id LEFT JOIN wms_cart c ON c.id = i.cart_id LEFT JOIN sys_user su ON su.id = i.updated_by LEFT JOIN ( SELECT cart_id, COUNT(*) AS cnt FROM wms_cart_item WHERE status = 1 GROUP BY cart_id ) ci ON ci.cart_id = i.cart_id
AND i.location_id = #{query.locationId}
AND i.aisle_id = #{query.aisleId}
AND i.point_code LIKE '%' || #{query.pointCode} || '%'
AND c.cart_code LIKE '%' || #{query.cartCode} || '%'
AND i.lock_status = #{query.lockStatus}
ORDER BY i.aisle_id ASC, i.point_code ASC
